// handleStream answers 200 even for a tab not handed over, with one ended event.
func (d Deps) handleStream(w http.ResponseWriter, r *http.Request) {
	h := w.Header()
	h.Set("Content-Type", "text/event-stream")
	h.Set("Cache-Control", "no-store")
	w.WriteHeader(http.StatusOK)
	sink := &sseSink{w: w, rc: http.NewResponseController(w)}
	ctx, cancel := context.WithCancel(r.Context())
	defer cancel()
	if err := d.Stream(ctx, r.PathValue("tab"), sink); err != nil {
		log.Printf("remote mode: stream: %v\n", err)
	}
}

