for {
	select {
	case err := <-done:
		if err != nil {
			log.Printf("remote mode: stream: %v\n", err)
		}
		return
	case <-beat.C:
		if err := sink.write(": ping\n\n"); err != nil {
			cancel()
			<-done
			return
		}
	}
}
